.ds-button { display: inline-flex; justify-content: center; align-items: center; gap: var(--space-2); min-height: 40px; padding: 0 var(--space-4); border: 1px solid transparent; border-radius: var(--radius-control); font-size: var(--text-sm); font-weight: 600; white-space: nowrap; transition: background-color var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out); }
.ds-button--primary { color: var(--color-on-accent); background: var(--color-accent); box-shadow: var(--shadow-control); }
.ds-button--primary:hover:not(:disabled) { background: var(--color-accent-hover); }
.ds-button--secondary { background: var(--color-surface-raised); border-color: var(--color-border); }
.ds-button--secondary:hover:not(:disabled) { background: #373e38; border-color: var(--color-border-strong); }
.ds-button--ghost { background: transparent; color: var(--color-text-secondary); }
.ds-button--ghost:hover:not(:disabled), .ds-button--ghost[aria-pressed='true'] { background: rgb(245 244 237 / 9%); color: var(--color-text); }
.ds-button--danger { color: var(--color-danger); background: rgb(244 170 164 / 8%); border-color: rgb(244 170 164 / 25%); }
.ds-button--danger:hover:not(:disabled) { background: rgb(244 170 164 / 15%); }
.ds-button:active:not(:disabled) { translate: 0 1px; }
.ds-button:disabled { opacity: .45; }
.ds-button--sm { min-height: 34px; padding-inline: var(--space-3); border-radius: var(--radius-sm); }
.ds-button--icon { width: 40px; padding: 0; }
.ds-button--icon.ds-button--sm { width: 34px; }
.ds-button {font-family:var(--font-ui);font-size:var(--text-sm);line-height:1.55;color:var(--color-text);cursor:pointer;} .ds-button:disabled {cursor:not-allowed;} .ds-button:focus-visible {box-shadow:var(--focus-ring);outline:2px solid transparent;}
@media (prefers-reduced-motion:reduce) { * {transition-duration:.01ms !important;animation-duration:.01ms !important;animation-iteration-count:1 !important;} }

