.ds-field { display: grid; gap: 8px; }
.ds-field label { font-size: var(--text-sm); font-weight: 600; }
.ds-text-input { background: var(--color-canvas); border: 1px solid var(--color-border-strong); border-radius: var(--radius-control); height: 44px; padding: 0 12px; width: 100%; min-width: 0; }
.ds-text-input::placeholder { color: var(--color-text-muted); }
.ds-text-input:hover { border-color: var(--color-text-muted); }
.ds-text-input[aria-invalid='true'] { border-color: var(--color-danger); }
.ds-field-hint { display: block; color: var(--color-text-muted); font-size: var(--text-sm); font-weight: 400; line-height: 1.6; }
.ds-field-error { color: var(--color-danger); } .ds-field {font-family:var(--font-ui);font-size:var(--text-base);line-height:1.55;color:var(--color-text);} .ds-text-input {font:inherit;color:inherit;} .ds-text-input:focus-visible {box-shadow:var(--focus-ring);outline:2px solid transparent;}

.ds-badge { display: inline-flex; align-items: center; width: fit-content; padding: 3px 8px; border: 1px solid var(--color-border); border-radius: var(--radius-xs); font-size: var(--text-xs); font-weight: 500; color: var(--color-text-secondary); background: rgb(245 244 237 / 4%); white-space: nowrap; }
.ds-badge--accent { color: var(--color-accent); border-color: rgb(237 197 140 / 20%); background: var(--color-selection); }
.ds-badge--success { color: var(--color-success); border-color: rgb(175 206 175 / 20%); background: rgb(175 206 175 / 9%); }
.ds-badge--danger { color: var(--color-danger); border-color: rgb(244 170 164 / 20%); background: rgb(244 170 164 / 9%); } .ds-badge {font-family:var(--font-ui);line-height:1.55;}

.ds-glass-panel { border: 1px solid var(--color-border); border-radius: var(--radius-panel); background: var(--surface-glass-default); -webkit-backdrop-filter: blur(var(--glass-blur)); backdrop-filter: blur(var(--glass-blur)); box-shadow: var(--shadow-panel); }
.ds-glass-panel--light { background: var(--surface-glass-light); }
.ds-glass-panel--dense { background: var(--surface-glass-dense); } .ds-glass-panel {font-family:var(--font-ui);font-size:var(--text-base);line-height:1.55;color:var(--color-text);padding:var(--space-6);} @supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))) {.ds-glass-panel {background:var(--color-surface);}}

.ds-segmented-control { display: inline-flex; gap: 3px; padding: 4px; margin: 0; min-width: 0; border: 1px solid var(--color-border); border-radius: var(--radius-md); background: var(--color-canvas); }
.ds-segment { position: relative; display: inline-flex; align-items: center; gap: 8px; min-height: 36px; padding: 0 14px; border-radius: var(--radius-control); font-size: var(--text-sm); color: var(--color-text-secondary); cursor: pointer; }
.ds-segment input { position: absolute; opacity: 0; width: 100%; height: 100%; inset: 0; margin: 0; cursor: pointer; }
.ds-segment:has(:focus-visible) { box-shadow: var(--focus-ring); }
.ds-segment:has(:checked) { color: var(--color-text); background: var(--color-surface-raised); }
.ds-segment:hover:not(:has(:checked)) { background: var(--color-surface); } .ds-segmented-control {font-family:var(--font-ui);font-size:var(--text-base);line-height:1.55;color:var(--color-text);}

.ds-toggle-row { position: relative; display: flex; justify-content: space-between; align-items: center; gap: 24px; min-height: 44px; cursor: pointer; }
.ds-toggle-label { font-weight: 500; }
.ds-toggle-row input { position: absolute; right: 0; width: 44px; height: 44px; opacity: 0; margin: 0; cursor: pointer; }
.ds-toggle-track { flex-shrink: 0; width: 38px; height: 23px; padding: 3px; border: 1px solid var(--color-border-strong); border-radius: var(--radius-pill); background: var(--color-surface-raised); transition: background-color var(--duration-fast) var(--ease-out); pointer-events: none; }
.ds-toggle-track span { display: block; width: 15px; height: 15px; border-radius: 50%; background: var(--color-text-secondary); transition: transform var(--duration-normal) var(--ease-out); }
.ds-toggle-row input:checked + .ds-toggle-track { background: var(--color-accent); }
.ds-toggle-row input:checked + .ds-toggle-track span { transform: translateX(15px); background: var(--color-on-accent); }
.ds-toggle-row input:focus-visible + .ds-toggle-track { box-shadow: var(--focus-ring); } .ds-toggle-row {font-family:var(--font-ui);font-size:var(--text-base);line-height:1.55;color:var(--color-text);}
